<div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Дата</th><th>Раздел</th><th>Товар / объект</th><th>Автор</th><th>Проверка</th></tr></thead><tbody>
<?php foreach($workflowHistory['items']as$event):?><tr><td><?=h($event['changed_at'])?></td><td><?=h(\app\services\CatalogWorkflow::HISTORY[$event['kind']])?><br><small><?=$event['kind']==='display'?'Версия':'Событие'?> #<?=(int)$event['event_id']?></small></td><td><?php if($event['product_id']):?><a href="<?=ADMIN?>/catalog-workflow/product?id=<?=(int)$event['product_id']?>"><?=h($event['sku']?:'#'.$event['product_id'])?></a><br><?=h($event['name']??'Удалённый товар')?><?php else:?><?=h($event['subject'])?><?php endif ?></td><td>ID <?=(int)$event['actor_id']?></td><td><a href="<?=ADMIN.h($event['url'])?>">Открыть раздел</a></td></tr><?php endforeach ?>
<?php if(!$workflowHistory['items']):?><tr><td colspan="5">Событий для выбранных условий нет.</td></tr><?php endif ?>
</tbody></table></div>
